#include <stdio.h>

int main(void) {
    int count = 0;
    for (int i = 0; i < 4; i++) {
        int num;
        scanf("%d", &num);
        if (num % 2 == 0) count++;
    }
    printf("%d\n", count);
    return 0;
}

#include <stdio.h>

int main(void) {
    int sum = 0;
    for (int i = 0; i < 4; i++) {
        int num;
        scanf("%d", &num);
        if (num % 2 == 0) sum += num;
    }
    printf("%d\n", sum);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int sum = 0;
    for (int i = 1; i <= n; i++) sum += i;
    printf("%d\n", sum);
    return 0;
}

